insert into public.products (id,category_id,name,name_en,slug,description,description_en,sku,price,sale_price,images,stock_status,is_active,sort_order) values
('12dd1b5d-9aa6-49ac-8c17-f2a318ce746e','5ecc6bbc-00c4-4a7b-b16a-0e2354bd82d9','תומך ספרים רוכב אופניים - The Apex Lean','Bicycle Rider Bookend - The Apex Lean','tvmk-sprym-rvkb-avpnyym-the-apex-lean-lb0ivy','<p><strong>תומך ספרים בעיצוב רוכב אופני כביש</strong></p><p><br></p><p>למי שחי את הכביש, סופר קילומטרים ורודף אחרי המהירות, אבל יודע גם להאט עם ספר טוב. זהו לא תומך ספרים רגיל; הוא מחזיק את אוסף הספרים שלכם בזווית דינמית ומלאת אופי, הלוכדת את הרגע המרגש של רוכב אופני כביש הנכנס עמוק אל תוך פנייה חדה.</p><p><br></p><p>יותר מתומך ספרים פונקציונלי, זהו גם פסל מדף מרשים המכניס לחלל תחושת תנועה, אנרגיה ותשוקה לרכיבה. מתנה מושלמת לרוכבי אופניים, לחובבי ספורט ולכל מי שמעריך עיצוב נקי בהשראת תנועה ומהירות.</p><p><br></p><p>מיוצר ממתכת איכותית ועמידה, בגימור צביעה בתנור לקבלת עמידות מרבית ומראה מוקפד לאורך שנים.</p><p><br></p><p><strong>חומר:</strong> מתכת</p><p><strong>צבע:</strong> שחור</p><p><strong>מידות:</strong> 24.8 × 9.5 × 7.7 ס”מ</p><p><strong>משקל:</strong> 174 גרם</p>','<p><strong>Bookend Designed as a Road Cyclist</strong></p><p><br></p><p>For those who live for the road, count every kilometer, and chase speed — but also know how to slow down with a good book. This is no ordinary bookend; it holds your book collection at a dynamic, character-filled angle, capturing the thrilling moment of a road cyclist leaning deep into a sharp turn.</p><p><br></p><p>More than a functional bookend, it is also an impressive shelf sculpture that brings a sense of movement, energy, and passion for cycling into any space. A perfect gift for cyclists, sports enthusiasts, and anyone who appreciates clean design inspired by motion and speed.</p><p><br></p><p>Crafted from high-quality, durable metal with a powder-coat oven finish for maximum durability and a refined look that lasts for years.</p><p><br></p><p><strong>Material:</strong> Metal</p><p><strong>Color:</strong> Black</p><p><strong>Dimensions:</strong> 24.8 × 9.5 × 7.7 cm</p><p><strong>Weight:</strong> 174 grams</p>','AD296',89.00,NULL,ARRAY['assets/product-1780850414494-e3q9du.webp','assets/product-1783186450936-qgk5j.webp','assets/product-1783186457937-4apde9.webp','assets/product-1783186464670-bruzx7.webp']::text[],'in_stock',true,0),
('eac2d590-849e-4362-a3e7-2dc02af4f592','fd8c7c93-54e7-47fe-8d92-606f2ae8b519','הטייה מלאה - תומך ספרים מעוצב כאופנוע ספורט','Full Lean - Designer Bookend Shaped Like a Sport Motorcycle','htyyh-mlah-tvmk-sprym-mavtsb-kavpnva-spvrt-pz6mae','<p>למי שחי את החיים במסלול המהיר אבל עדיין נהנה לעצור לרגע עם ספר טוב. זהו לא תומך ספרים רגיל – הוא מחזיק את הספרים בזווית דרמטית ודינמית, המדמה אופנוע ספורט החותך פנייה חדה בהטיה מלאה.</p><p><br></p><p>יותר מתומך ספרים, זהו גם פסל מדף מרשים שמוסיף אופי ותנועה לכל חלל. מתנה מושלמת לחובבי אופנועים ולכל מי שמרגיש את הריגוש של הרכיבה גם כשהוא לא על הכביש.</p><p><br></p><p>מיוצר ממתכת איכותית ועמידה, בגימור צביעה בתנור לשמירה על מראה מרשים לאורך שנים.</p>','<p>For those who live life in the fast lane but still enjoy stopping for a moment with a good book. This is not an ordinary bookend – it holds books at a dramatic and dynamic angle, mimicking a sport motorcycle cutting through a sharp turn in full lean.</p><p><br></p><p>More than a bookend, this is also an impressive shelf sculpture that adds character and movement to any space. A perfect gift for motorcycle enthusiasts and anyone who feels the thrill of riding even when not on the road.</p><p><br></p><p>Made from high-quality, durable metal with an oven-baked paint finish to maintain an impressive appearance for years.</p>','AD295',89.00,NULL,ARRAY['assets/product-1781191148367-34mtvt.webp','assets/product-1781191141170-eg005fh.webp','assets/product-1781191117553-zyso6.webp','assets/product-1781191125700-8ea5ca.webp','assets/product-1781191133560-0yo57.webp','assets/product-1781191944596-25yzx.webp','assets/product-1781191969969-gfdiors.webp']::text[],'in_stock',true,0),
('5d4958df-e718-45e0-b8ce-1d6ec377ca62','fd8c7c93-54e7-47fe-8d92-606f2ae8b519','בננה ביץ׳ - מתלה לבננות','Banana Beach - Banana Hanger','bnnh-byts-mtlh-lbnnvt-myuhh2','<p class="ql-align-right"><strong>בננה ביץ׳</strong> – מתלה בננות מעוצב ממתכת</p><p class="ql-align-right">מתלה מעוצב ומקסים לבננות למטבח, מעוצב בהשראת חוף ים טרופי, עם עץ דקל ואישה נופשת ונינוחה.</p><p class="ql-align-right">פריט מקורי, יפיפה ודקורטיבי לקישוט המטבח. משרה פסטורליות ורוגע.</p><p class="ql-align-right">רוצים אריכות ימים לבננות שלכם?</p><p class="ql-align-right">מחזיק הבננות שלנו הוא לא רק דקורטיבי, הוא גם פונקציונלי!</p><p class="ql-align-right">כשתולים את הבננות על מתלה מוגבה במקום להניח אותן בקערה, הן נשמרות טריות לאורך זמן, כי התליה שלהן בגובה מפחיתה סימני לחץ והשחרה שנוצרים ממגע עם משטח.</p><p class="ql-align-right">גם מגע עם פירות אחרים מקצר את חיי הבננות, ולכן שימוש במתלה המעוצב מאריך את חייהן.</p><p class="ql-align-right">מתאים כפריט עיצוב למטבח, כמתנה מקורית לבית חדש, או לכל מי שאוהב לשלב פונקציונליות עם עיצוב מרגש..</p><p class="ql-align-right"><br></p><p class="ql-align-right"><br></p><p class="ql-align-justify"><br></p>','<p class="ql-align-right"><strong>Banana Beach</strong> – A designer metal banana hanger</p><p class="ql-align-right">A beautifully designed and charming banana hanger for the kitchen, inspired by a tropical beach, featuring a palm tree and a relaxed, leisurely woman.</p><p class="ql-align-right">An original, gorgeous, and decorative piece to adorn your kitchen. It radiates a sense of pastoral calm and tranquility.</p><p class="ql-align-right">Want your bananas to last longer?</p><p class="ql-align-right">Our banana holder is not just decorative – it''s functional too!</p><p class="ql-align-right">When you hang bananas on an elevated hanger instead of placing them in a bowl, they stay fresh for longer, because hanging them at height reduces pressure marks and browning caused by contact with a surface.</p><p class="ql-align-right">Contact with other fruits also shortens the life of bananas, so using the designer hanger extends their lifespan.</p><p class="ql-align-right">Perfect as a kitchen décor item, an original housewarming gift, or for anyone who loves combining functionality with stunning design..</p><p class="ql-align-right"><br></p><p class="ql-align-right"><br></p><p class="ql-align-justify"><br></p>','AD355',169.90,NULL,ARRAY['assets/product-1778418461929-i0iixh4.webp','assets/product-1778418438004-vzf3umd.webp','assets/product-1778418443267-bvv741.webp','assets/product-1778418449534-af425p.webp','assets/product-1778418455925-oza7yg.webp','assets/product-1780909816779-gvjdhh.webp']::text[],'in_stock',true,0),
('5b5c7853-c985-4569-82d1-8492bcdc2e91','a286ff99-35e4-4423-b957-af27f3f4e45f','ביזי חיילים - בן - מעמד לטלפון נייד','Busy Soldiers - Ben - Mobile Phone Stand','byzy-chyylym-bn-mamd-ltlpvn-nyyd-chilqp','<p class="ql-align-right">.זה לא סתם מעמד לטלפון, זה פריט מקורי ואלגנטי שמוסיף אופי לשולחן העבודה, בעיצוב של צללית של חייל אמיץ</p><p class="ql-align-right">.עיצוב שמבטא מוכנות, הגנה ומסירות בלתי מתפשרת</p><p class="ql-align-right"><br></p><p class="ql-align-right">.בין אם אתם עובדים, לומדים, צופים בתוכן או משוחחים שיחת וידאו - הטלפון שלכם מונח בבטחה, תוך שהוא משקף את רוחם של מי שמגינים ומשרתים</p><p class="ql-align-right"><br></p><p class="ql-align-right">פרקטי ובעל נוכחות</p><p class="ql-align-right">אידיאלי לשולחן עבודה, לשימוש בבית או כפריט עם משמעות</p><p class="ql-align-right"><br></p><p class="ql-align-right">יציב ואמין</p><p class="ql-align-right">מחזיק את הטלפון בצורה בטוחה, לאורך או לרוחב</p><p class="ql-align-right"><br></p><p class="ql-align-right">מתנה מושלמת לחייל, לבני משפחה המתגעגעים ליקירם במדים, למתגייסים, או כמזכרת משמעותית לשחרור</p><p class="ql-align-right"><br></p>','<p class="ql-align-right">This is not just a phone stand, it''s an original and elegant item that adds character to your desk, designed with the silhouette of a brave soldier.</p><p class="ql-align-right">A design that expresses readiness, protection and unwavering dedication.</p><p class="ql-align-right"><br></p><p class="ql-align-right">Whether you''re working, studying, watching content or having a video call - your phone rests securely, while reflecting the spirit of those who protect and serve.</p><p class="ql-align-right"><br></p><p class="ql-align-right">Practical and with presence</p><p class="ql-align-right">Ideal for a work desk, home use or as a meaningful item</p><p class="ql-align-right"><br></p><p class="ql-align-right">Stable and reliable</p><p class="ql-align-right">Holds the phone securely, portrait or landscape</p><p class="ql-align-right"><br></p><p class="ql-align-right">Perfect gift for a soldier, for family members missing their loved one in uniform, for new recruits, or as a meaningful memento for discharge</p><p class="ql-align-right"><br></p>','AD333',55.00,NULL,ARRAY['assets/product-1777395937779-hxiw2.webp','assets/product-1777395753387-g47l6g.webp','assets/product-1777395759029-tavswl.webp','assets/product-1777395764776-jn4s9yp.webp','assets/product-1777395770448-w6thof.webp']::text[],'in_stock',true,0),
